package com.vectora.api;
import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") @CrossOrigin(origins="*") public class VectoraController {private final VectoraRepository repo;public VectoraController(VectoraRepository repo){this.repo=repo;} @GetMapping({"/",""}) public Map<String,String> info(){return Map.of("name","Vectora Operations","docs","/swagger-ui/index.html");} @GetMapping("/dashboard") public Map<String,Object> dashboard(){return repo.dashboard();} @GetMapping("/cameras") public List<Map<String,Object>> cameras(){return repo.cameras();} @GetMapping("/sensors") public List<Map<String,Object>> sensors(){return repo.sensors();} @GetMapping("/drones") public List<Map<String,Object>> drones(){return repo.drones();} @GetMapping("/missions") public List<Map<String,Object>> missions(){return repo.missions();} @GetMapping("/geofences") public List<Map<String,Object>> geofences(){return repo.geofences();} @GetMapping("/events") public List<Map<String,Object>> events(){return repo.events();} @GetMapping("/audit") public List<Map<String,Object>> audit(){return repo.audit();} @PostMapping("/simulation") @ResponseStatus(HttpStatus.ACCEPTED) public Map<String,Object> simulation(@RequestParam String type,@RequestParam(defaultValue="SIM-001") String source){repo.simulate(type,source);return Map.of("accepted",true,"type",type,"source",source);} }
